        return jsonify({'error': 'Invalid input, please enter an integer'})

if __name__ == '__main__':
    app.run()
```
This API defines two functions `is_prime()` and `get_next_prime()` which are used to check if a number is prime and to find the next prime number respectively. The API utilizes the Flask web framework to create an endpoint '/nextprime/' that accepts an integer as input and returns the next prime number in JSON format. The API also includes error handling to return an error message in case the input is invalid.

Here is a C++ program to reverse the elements of an array:

```c++
#include <iostream>

using namespace std;

void reverseArray(int arr[], int n) {
    // Initialize start and end indexes
    int start = 0;
    int end = n-1;
    // Loop over half the array
    while (start < end) {
        // Swap the values at start and end
        int temp = arr[start]; 
        arr[start] = arr[end];
        arr[end] = temp;
        // Increment start and decrement end
        start++;
        end--;
    }
}

void printArray(int arr[], int n) { 
    // Loop over the array and print out the values
    for (int i = 0; i < n; i++) 
        cout << arr[i] << " "; 
    cout << endl; 
} 

int main() {
    int arr[] = {1, 2, 3, 4, 5, 6};
    int n = sizeof(arr)/sizeof(arr[0]);

    cout << "Original array: ";
    printArray(arr, n);

    // Reverse the array
    reverseArray(arr, n); 

    cout << "Reversed array: ";
    printArray(arr, n);

    return 0;
}
```

